import importlib.util, io, math, os, random, re, signal, sys, tokenize
P = '/tmp/eval_attn/attention.py'


def fail(msg):
    print('FAIL: ' + msg)
    sys.exit(1)


if not os.path.isfile(P):
    fail('attention.py not found')
src = open(P).read()


def code_only(s):
    out = []
    try:
        for tok in tokenize.generate_tokens(io.StringIO(s).readline):
            out.append(' ' if tok.type in (tokenize.COMMENT, tokenize.STRING) else tok.string)
    except Exception:
        return s
    return ' '.join(out)


if re.search(r'(?m)^\s*(?:import|from)\s+(?:numpy|torch)\b', code_only(src)):
    fail('must not import numpy or torch')


class _Timeout(Exception):
    pass


def _alarm(*_):
    raise _Timeout()


signal.signal(signal.SIGALRM, _alarm)
signal.alarm(10)
try:
    spec = importlib.util.spec_from_file_location('attention_sol', P)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    attention = mod.attention
except _Timeout:
    fail('solution timed out (limit 10s)')
except BaseException as e:
    fail('import raised ' + type(e).__name__)


def ref(Q, K, V):
    scale = 1.0 / math.sqrt(len(Q[0]))
    out = []
    for q in Q:
        s = [math.fsum(a * b for a, b in zip(q, k)) * scale for k in K]
        m = max(s)
        e = [math.exp(x - m) for x in s]
        z = math.fsum(e)
        out.append([math.fsum(w * v[j] for w, v in zip(e, V)) / z for j in range(len(V[0]))])
    return out


rng = random.Random(0xA77E)
mat = lambda r, c, a: [[rng.uniform(-a, a) for _ in range(c)] for _ in range(r)]
cases = [([[1.0, 0.0]], [[1.0, 0.0], [0.0, 1.0]], [[1.0, 2.0], [3.0, 4.0]]),
         ([[100.0, 0.0], [0.0, 100.0]], [[1.0, 0.0], [0.0, 1.0]], [[10.0], [20.0]]),
         ([[1500.0, 0.0], [0.0, 1500.0]], [[1.0, 0.0], [0.0, 1.0]], [[10.0], [20.0]]),
         ([[-1500.0, -1500.0]], [[1.0, 0.0], [0.0, 1.0]], [[3.0, -1.0], [5.0, 2.0]]),
         ([[0.5, -0.25, 1.0]], [[0.1, 0.2, 0.3]], [[7.0, -7.0]])]
for _ in range(45):
    nq, nk, dk, dv = rng.randint(1, 6), rng.randint(1, 8), rng.randint(1, 6), rng.randint(1, 4)
    cases.append((mat(nq, dk, 2.0), mat(nk, dk, 2.0), mat(nk, dv, 3.0)))
for _ in range(15):
    nq, nk, dk, dv = rng.randint(1, 4), rng.randint(2, 6), rng.randint(1, 4), rng.randint(1, 3)
    big = rng.uniform(300.0, 3000.0)
    cases.append((mat(nq, dk, big), mat(nk, dk, 1.0), mat(nk, dv, 3.0)))
for i, (Q, K, V) in enumerate(cases):
    want = ref(Q, K, V)
    try:
        got = attention([r[:] for r in Q], [r[:] for r in K], [r[:] for r in V])
    except _Timeout:
        fail('solution timed out (limit 10s)')
    except BaseException as e:
        fail('case %d: raised %s' % (i, type(e).__name__))
    try:
        rows = [list(r) for r in got]
        ok = len(rows) == len(want) and all(len(r) == len(w) for r, w in zip(rows, want))
    except BaseException:
        ok = False
    if not ok:
        fail('case %d: wrong output shape' % i)
    for r, w in zip(rows, want):
        for g, x in zip(r, w):
            try:
                good = abs(float(g) - x) <= 1e-6 * max(1.0, abs(x))
            except BaseException:
                good = False
            if not good:
                fail('mismatch at case %d' % i)
signal.alarm(0)
print('OK: %d hidden cases' % len(cases))
